def equation(eps, T, params):
    p=params
    L=np.log(eps)
    g=eps**(p[8]+p[9]*T)
    return p[0]+p[1]*T+p[2]*T**2+p[3]*T**3+(p[4]+p[5]*T+p[6]*T**2)*L+p[7]*g*(1+0*T)

